statement-execution-processor.statement:
DECLARE
    v_prompt   CLOB;
    v_response CLOB;
BEGIN
WITH ranked AS (
    SELECT CONTENT
        FROM REPORTS_NO_WEEK rnw
        ORDER BY vector_distance(
                    rnw.EMBEDDING_TITLE,
                    vector_embedding(doc_model
                            USING {#0} AS data)
        ) ASC
    FETCH FIRST 5 ROWS ONLY
), prompt_text AS (
        SELECT LISTAGG(CONTENT, CHR(10))
        WITHIN GROUP (ORDER BY NULL) AS prompt
        FROM ranked
        )
SELECT prompt
        INTO v_prompt
        FROM prompt_text;

v_response := DBMS_VECTOR.UTL_TO_GENERATE_TEXT(
v_prompt,
    JSON({#1})
);

? := v_response;
END;

begin
    DBMS_VECTOR.LOAD_ONNX_MODEL_CLOUD(
        MODEL_NAME => {#0},
        CREDENTIAL => {#1},
        URI        => {#2});
end;

select
    CHUNK_OFFSET as "Chunk offset",
    CHUNK_LENGTH as "Chunk length",
    CHUNK_TEXT as "Chunk text"
from VECTOR_CHUNKS(
    {#0}
    BY {1}
    MAX {2}
    OVERLAP {3}
    SPLIT BY {4})
